INSERT INTO setting_template_refs(tenant_id,id,subject,kind,template_key,entity_id) SELECT t.tenant_id,'tref_'||lower(hex(randomblob(12))),'art_interest','report_classes','r_80f00bb6035a',t.id FROM report_classes t JOIN tenant_subjects s ON s.tenant_id=t.tenant_id AND s.id=t.subject WHERE t.subject='art_interest' AND t.source='template' AND t.version=1 AND t.name='创意美术' AND s.pack_version='0.1';
